import urwid
import sys
import os

class LazyTextWalker(urwid.ListWalker):
    def __init__(self, filename):
        self.filename = filename
        self.lines = []
        self.focus = 0
        self._file_loaded = False
        self._load_file()

    def _load_file(self):
        if not self._file_loaded:
            if os.path.exists(self.filename):
                with open(self.filename, 'r', encoding='utf-8') as f:
                    self.lines = [line.rstrip('\n') for line in f]
            else:
                self.lines = ['']
            self._file_loaded = True

    def get_focus(self):
        return self._get_at_pos(self.focus)

    def set_focus(self, focus):
        self.focus = focus
        self._modified()

    def get_next(self, pos):
        return self._get_at_pos(pos + 1)

    def get_prev(self, pos):
        return self._get_at_pos(pos - 1)

    def _get_at_pos(self, pos):
        if 0 <= pos < len(self.lines):
            return EditableLine(self, pos), pos
        return None, None

    def insert_line(self, pos, text=''):
        self.lines.insert(pos, text)
        self._modified()

    def delete_line(self, pos):
        if len(self.lines) > 1:
            del self.lines[pos]
            self._modified()

    def save(self):
        with open(self.filename, 'w', encoding='utf-8') as f:
            for line in self.lines:
                f.write(line + '\n')

class EditableLine(urwid.WidgetWrap):
    def __init__(self, walker, pos):
        self.walker = walker
        self.pos = pos
        self.edit = urwid.Edit('', walker.lines[pos])
        super().__init__(self.edit)

    def selectable(self):
        return True

    def keypress(self, size, key):
        return self.edit.keypress(size, key)

    def get_edit_text(self):
        return self.edit.edit_text

    def set_edit_text(self, text):
        self.edit.set_edit_text(text)

    def get_edit_pos(self):
        return self.edit.edit_pos

    def set_edit_pos(self, pos):
        self.edit.edit_pos = pos

class TextEditor(urwid.WidgetWrap):
    def __init__(self, filename):
        self.filename = filename
        self.walker = LazyTextWalker(filename)
        self.listbox = urwid.ListBox(self.walker)
        self.footer = urwid.Text(
            u"Ctrl+S: Save | Ctrl+Q: Quit | Enter: New Line | Backspace/Delete: Remove | ←/→: Move"
        )
        self.frame = urwid.Frame(self.listbox, footer=self.footer)
        super().__init__(self.frame)

    def keypress(self, size, key):
        if key == 'ctrl s':
            self.walker.save()
            self.footer.set_text("Saved! Ctrl+S: Save | Ctrl+Q: Quit | Enter: New Line | Backspace/Delete: Remove | ←/→: Move")
            return
        elif key == 'ctrl q':
            raise urwid.ExitMainLoop()
        focus_widget, focus_pos = self.walker.get_focus()
        if focus_widget is None:
            return
        edit = focus_widget
        edit_text = edit.get_edit_text()
        edit_pos = edit.get_edit_pos()
        # Navigation
        if key == 'left':
            if edit_pos > 0:
                edit.set_edit_pos(edit_pos - 1)
            elif focus_pos > 0:
                prev_widget, prev_pos = self.walker.get_prev(focus_pos)
                if prev_widget:
                    self.walker.set_focus(prev_pos)
                    prev_widget.set_edit_pos(len(prev_widget.get_edit_text()))
        elif key == 'right':
            if edit_pos < len(edit_text):
                edit.set_edit_pos(edit_pos + 1)
            elif focus_pos < len(self.walker.lines) - 1:
                next_widget, next_pos = self.walker.get_next(focus_pos)
                if next_widget:
                    self.walker.set_focus(next_pos)
                    next_widget.set_edit_pos(0)
        # New line
        elif key == 'enter':
            left = edit_text[:edit_pos]
            right = edit_text[edit_pos:]
            self.walker.lines[focus_pos] = left
            self.walker.insert_line(focus_pos + 1, right)
            self.walker.set_focus(focus_pos + 1)
            next_widget, _ = self.walker.get_focus()
            next_widget.set_edit_pos(0)
        # Backspace
        elif key == 'backspace':
            if edit_pos > 0:
                new_text = edit_text[:edit_pos - 1] + edit_text[edit_pos:]
                edit.set_edit_text(new_text)
                edit.set_edit_pos(edit_pos - 1)
                self.walker.lines[focus_pos] = new_text
            elif focus_pos > 0:
                prev_widget, prev_pos = self.walker.get_prev(focus_pos)
                prev_text = prev_widget.get_edit_text()
                new_text = prev_text + edit_text
                self.walker.lines[prev_pos] = new_text
                self.walker.delete_line(focus_pos)
                self.walker.set_focus(prev_pos)
                prev_widget, _ = self.walker.get_focus()
                prev_widget.set_edit_text(new_text)
                prev_widget.set_edit_pos(len(prev_text))
        # Delete
        elif key == 'delete':
            if edit_pos < len(edit_text):
                new_text = edit_text[:edit_pos] + edit_text[edit_pos + 1:]
                edit.set_edit_text(new_text)
                self.walker.lines[focus_pos] = new_text
            elif focus_pos < len(self.walker.lines) - 1:
                next_widget, next_pos = self.walker.get_next(focus_pos)
                next_text = next_widget.get_edit_text()
                new_text = edit_text + next_text
                self.walker.lines[focus_pos] = new_text
                self.walker.delete_line(next_pos)
                edit.set_edit_text(new_text)
                edit.set_edit_pos(edit_pos)
        else:
            res = edit.keypress(size, key)
            self.walker.lines[focus_pos] = edit.get_edit_text()
            return res

def main(filename):
    editor = TextEditor(filename)
    loop = urwid.MainLoop(editor, unhandled_input=editor.keypress)
    loop.run()

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print("Usage: python text_editor.py <filename>")
        sys.exit(1)
    main(sys.argv[1])
